arguments.content:
@tailwind base;
@tailwind components;
@tailwind utilities;

/* ─── Editorial Design Tokens ──────────────────────────────────────────────── */

:root {
  /* Color — warm paper editorial palette */
  --color-paper:      #f5f1eb;
  --color-ink:        #1a1714;
  --color-muted:      #6b6560;
  --color-faint:      #c8c2ba;
  --color-oxblood:    #7a1d1d;
  --color-accent:     #9b3b1e;
  --color-hairline:   #ddd8d0;
  --color-surface:    #ede9e2;

  /* Typography */
  --font-serif:       'Spectral', 'Plantin', 'Georgia', serif;
  --font-sans:        'Inter', system-ui, -apple-system, sans-serif;

  /* Type scale (fluid) */
  --text-xs:          0.75rem;
  --text-sm:          0.875rem;
  --text-base:        1.0625rem;
  --text-lg:          1.25rem;
  --text-xl:          1.5rem;
  --text-2xl:         2rem;
  --text-3xl:         2.75rem;
  --text-4xl:         3.75rem;
  --text-5xl:         5rem;

  /* Leading */
  --leading-tight:    1.15;
  --leading-snug:     1.35;
  --leading-prose:    1.7;

  /* Tracking */
  --tracking-tight:   -0.02em;
  --tracking-wide:    0.08em;
  --tracking-caps:    0.12em;

  /* Spacing rhythm */
  --space-1:          0.25rem;
  --space-2:          0.5rem;
  --space-3:          0.75rem;
  --space-4:          1rem;
  --space-6:          1.5rem;
  --space-8:          2rem;
  --space-12:         3rem;
  --space-16:         4rem;
  --space-24:         6rem;
  --space-32:         8rem;
  --space-48:         12rem;

  /* Max-width column */
  --col-prose:        68ch;
  --col-wide:         90rem;

  /* Transitions */
  --ease-out:         cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast:    120ms;
  --duration-base:    240ms;
  --duration-slow:    400ms;
}

/* ─── Base Layer ────────────────────────────────────────────────────────────── */

@layer base {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
  }

  body {
    font-family: var(--font-serif);
    font-size: var(--text-base);
    line-height: var(--leading-prose);
    background-color: var(--color-paper);
    color: var(--color-ink);
    overflow-x: hidden;
    /* Font rendering */
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-feature-settings: 'kern' 1, 'liga' 1, 'onum' 1;
    /* Balanced text wrapping (Chrome 114+, Firefox 121+) */
    text-wrap: pretty;
  }

  /* Headings default to serif */
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-serif);
    font-weight: 500;
    letter-spacing: var(--tracking-tight);
    line-height: var(--leading-tight);
    text-wrap: balance;
    color: var(--color-ink);
  }

  /* Focused elements — visible, consistent, branded */
  :focus-visible {
    outline: 2px solid var(--color-oxblood);
    outline-offset: 3px;
    border-radius: 2px;
  }

  /* Remove outline for mouse users */
  :focus:not(:focus-visible) {
    outline: none;
  }

  /* Links */
  a {
    color: inherit;
    text-decoration: none;
  }

  /* Images */
  img,
  picture,
  video,
  canvas,
  svg {
    display: block;
    max-width: 100%;
  }

  /* Form elements inherit typography */
  input,
  button,
  textarea,
  select {
    font: inherit;
  }

  /* Horizontal rule — hairline */
  hr {
    border: none;
    border-top: 1px solid var(--color-hairline);
  }
}

/* ─── Skip Link ─────────────────────────────────────────────────────────────── */

.skip-link {
  position: absolute;
  top: -100%;
  left: var(--space-4);
  z-index: 9999;
  padding: var(--space-2) var(--space-4);
  background: var(--color-ink);
  color: var(--color-paper);
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 0 0 4px 4px;
  transition: top var(--duration-fast) var(--ease-out);
}

.skip-link:focus {
  top: 0;
  outline: 2px solid var(--color-oxblood);
  outline-offset: 2px;
}

/* ─── Reduced Motion ────────────────────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ─── Utility Classes ───────────────────────────────────────────────────────── */

@layer utilities {
  .font-serif   { font-family: var(--font-serif); }
  .font-sans    { font-family: var(--font-sans); }

  .text-paper   { color: var(--color-paper); }
  .text-ink     { color: var(--color-ink); }
  .text-muted   { color: var(--color-muted); }
  .text-oxblood { color: var(--color-oxblood); }
  .text-accent  { color: var(--color-accent); }

  .bg-paper     { background-color: var(--color-paper); }
  .bg-surface   { background-color: var(--color-surface); }
  .bg-ink       { background-color: var(--color-ink); }

  .border-hairline { border-color: var(--color-hairline); }

  .tracking-caps   { letter-spacing: var(--tracking-caps); }
  .tracking-tight  { letter-spacing: var(--tracking-tight); }
  .tracking-wide   { letter-spacing: var(--tracking-wide); }

  .leading-prose  { line-height: var(--leading-prose); }
  .leading-tight  { line-height: var(--leading-tight); }
  .leading-snug   { line-height: var(--leading-snug); }

  .col-prose  { max-width: var(--col-prose); }
  .col-wide   { max-width: var(--col-wide); }
}

/** @type {import('tailwindcss').Config} */
module.exports = {
  content: [
    "./src/**/*.{js,jsx,ts,tsx}",
  ],
  theme: {
    extend: {
      fontFamily: {
        serif: ['Spectral', 'Plantin', 'Georgia', 'serif'],
        sans:  ['Inter', 'system-ui', '-apple-system', 'sans-serif'],
      },
      colors: {
        paper:    'var(--color-paper)',
        ink:      'var(--color-ink)',
        muted:    'var(--color-muted)',
        faint:    'var(--color-faint)',
        oxblood:  'var(--color-oxblood)',
        accent:   'var(--color-accent)',
        hairline: 'var(--color-hairline)',
        surface:  'var(--color-surface)',
      },
      maxWidth: {
        prose: 'var(--col-prose)',
        wide:  'var(--col-wide)',
      },
      lineHeight: {
        tight: 'var(--leading-tight)',
        snug:  'var(--leading-snug)',
        prose: 'var(--leading-prose)',
      },
      letterSpacing: {
        tight: 'var(--tracking-tight)',
        wide:  'var(--tracking-wide)',
        caps:  'var(--tracking-caps)',
      },
      transitionTimingFunction: {
        out: 'var(--ease-out)',
      },
    },
  },
  plugins: [],
}
